"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, List
from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans

Spans = Iterable[Span]

def check_inside(spans: Spans, opening: Span):
    """Raise ValueError if a span leaves opening hours."""
    for span in spans:
        if span.start < opening.start:
            raise ValueError(f"before opening: {span}")
        if span.end > opening.end:
            raise ValueError(f"after closing: {span}")

def gap_spans(worked: Spans, opening: Span) -> List[Span]:
    """Uncovered spans inside opening hours, in order."""
    edges = [opening.start]
    for span in merge_spans(worked):
        edges += [span.start, span.end]
    edges.append(opening.end)
    pairs = zip(edges[::2], edges[1::2])
    return [Span(a, b) for a, b in pairs if a < b]

def find_gaps(worked: Spans, opening: Span) -> List[str]:
    """Labels like gap 12:00-13:00 (60 min), one per gap."""
    worked = list(worked)
    check_inside(worked, opening)
    return [
        f"gap {format_span(gap)} ({gap.minutes} min)"
        for gap in gap_spans(worked, opening)
    ]

